public bool WordPatternTwoMaps(string pattern, string s)
{
    var words = s.Split(' ');
    if (words.Length != pattern.Length) return false;
    var p2w = new Dictionary<char, string>();
    var w2p = new Dictionary<string, char>();
    for (int i = 0; i < pattern.Length; i++)
    {
        char c = pattern[i]; string w = words[i];
        if (p2w.ContainsKey(c) && p2w[c] != w) return false;
        if (w2p.ContainsKey(w) && w2p[w] != c) return false;
        p2w[c] = w; w2p[w] = c;
    }
    return true;
}

public bool WordPattern(string pattern, string s)
{
    var words = s.Split(' ');
    if (words.Length != pattern.Length) return false;
    var p2i = new Dictionary<char, int>();
    var w2i = new Dictionary<string, int>();
    for (int i = 0; i < pattern.Length; i++)
    {
        if (!p2i.ContainsKey(pattern[i])) p2i[pattern[i]] = i;
        if (!w2i.ContainsKey(words[i])) w2i[words[i]] = i;
        if (p2i[pattern[i]] != w2i[words[i]]) return false;
    }
    return true;
}
